  Definition cR_pre (rg : bvmap 5 word) : Prop :=
    getr rg 10 = Z_to_bv 64 pd /\ getr rg 11 = Z_to_bv 64 ps /\ getr rg 12 = Z_to_bv 64 n /\ getr rg 8 = Z_to_bv 64 s
    /\ getr rg 19 = Z_to_bv 64 (ps + n) /\ getr rg 20 = Z_to_bv 64 (pd + n) /\ getr rg 2 = Z_to_bv 64 (s - 2160).
  Definition cR_post (rg : bvmap 5 word) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S?0|21;!1,20!1,2|600;!1+12|32;!1,44|33;!1,46!1,4|34;|30;!1,49!1,4|46;!1,4|44;|10;!1,4=$rg;R!2'_Q13!2+A!3+<3!2'_S#1!3,315vv,6!2'715!2'=2/pd;!2+A!3+<3!2'_S#1!3,317vv,6!2'717!2'=2/ps;!2+A!3+<3!2'_S#1!3,318vv,6!2'718!2'=2/n;!2+A!3+<3!2'_S#1!3,31:vv,6!2'71:!2'=2/s;!2+A!3+<3!2'_S#1!3,31;vv,6!2'71;!2'=2!2'H/n;!1,4|601;!2+A!3+<3!2'_S#1!3,31<vv,6!2'71<!2'=2!2'D/pd;/n;!3+<3!2'_S#1!3,31>vv,6!2'71>!2'=2!2'H/s;!1,4|;070;").

