  (* [comment removed for export] *)
  Definition qlW_inv (rg : bvmap 5 word) (i : Z) : Prop :=
    getr rg 13 = Z_to_bv 64 (fD + i) /\ getr rg 14 = Z_to_bv 64 lD /\ getr rg 15 = Z_to_bv 64 0 /\ getr rg 10 = Z_to_bv 64 pd /\ getr rg 11 = Z_to_bv 64 ps /\ getr rg 12 = Z_to_bv 64 n /\ getr rg 2 = Z_to_bv 64 (s - 2160).
  Definition qlW_post (rg : bvmap 5 word) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S:0|21;!1,20!1,2|600;!1+12!1,4|37;!1,4|32;!1,4|33;!1,4|34;|10;!1,48$rg;R!2'_Q13!2+A!3+<3!2'_S#1!3,314vv,6!2'714!2'=2,C!2+A!3+<3!2'_S#1!3,315vv,6!2'715!2'=2/pd;!2+A!3+<3!2'_S#1!3,316vv,6!2'716!2'=2/ps;!2+A!3+<3!2'_S#1!3,317vv,6!2'717!2'=2/n;!3+<3!2'_S#1!3,319vv,6!2'719!2'=2!2'H/s;!1,4|;070;").
